import{c as t,Q as o,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Exporting data","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/exports.md","filePath":"user/after-the-event/exports.md"}'),n={name:"user/after-the-event/exports.md"};function s(i,e,l,h,p,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="exporting-data" tabindex="-1">Exporting data <a class="header-anchor" href="#exporting-data" aria-label="Permalink to &quot;Exporting data&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers sharing results with federations, Eventor, or other systems.</p><p>How to export results and event data into the formats other systems expect.</p><blockquote><p><strong>Status:</strong> Stub — not yet written.</p></blockquote><h2 id="what-this-page-will-cover" tabindex="-1">What this page will cover <a class="header-anchor" href="#what-this-page-will-cover" aria-label="Permalink to &quot;What this page will cover&quot;">​</a></h2><ul><li>[ ] Exporting results as IOF XML</li><li>[ ] Exporting to Eventor</li><li>[ ] Exporting splits and tracking data</li><li>[ ] CSV exports for spreadsheet use</li><li>[ ] Archiving an event (self-contained backup of all its data)</li><li>[ ] What to do with the event folder after the competition</li></ul><h2 id="exporting-one-country-s-results" tabindex="-1">Exporting one country&#39;s results <a class="header-anchor" href="#exporting-one-country-s-results" aria-label="Permalink to &quot;Exporting one country&#39;s results&quot;">​</a></h2><p><strong>Publish → Export IOF XML</strong> and <strong>Publish → Export JSON</strong> open a dialog that, alongside the classes, asks which <strong>Countries</strong> to include. Everything starts selected, so the file carries every country unless you untick some — handy when a national federation wants only its own runners.</p><ul><li>A competitor&#39;s country is their <strong>club&#39;s</strong>. A relay team goes by the team&#39;s own club, so a team is always exported whole.</li><li><strong>No country</strong> covers competitors whose club has no country recorded (or has a dash, <code>-</code>, where the code would be), and competitors with no club at all.</li><li>Places are not renumbered. A runner who came fourth in the class is fourth in the file, whoever else was left out.</li><li>The list only appears when there is more than one choice — a single country plus <strong>No country</strong> counts. The PDF, Print and <strong>Upload to Eventor</strong> actions don&#39;t offer it: Eventor must get every runner in each class you upload, or it reads the rest as never having entered.</li></ul><p>Each country shows with the code its clubs were given. If some clubs were given the IOC code (<code>SUI</code>) and others the ISO code (<code>CHE</code>), both appear — tick both.</p><h2 id="exporting-the-entry-list" tabindex="-1">Exporting the entry list <a class="header-anchor" href="#exporting-the-entry-list" aria-label="Permalink to &quot;Exporting the entry list&quot;">​</a></h2><p>Who has entered — as opposed to when they start or how they got on — is exported from the <strong>Competitors</strong> page: <strong>Actions → Export entry list</strong>, in IOF XML, Orienteering JSON or CSV. It&#39;s written up where the menu lives: see <a href="./../event-setup/competitors-clubs-teams#exporting-the-entry-list">Exporting the entry list</a>.</p><p>Two things worth knowing before you reach for it:</p><ul><li><strong>The export is always the whole event</strong>, never the filtered list you&#39;re looking at.</li><li><strong>The CSV is designed to be edited and re-imported</strong> — though not every column comes back. The <a href="./../event-setup/competitors-clubs-teams#the-csv-round-trip">round-trip table</a> says which do.</li></ul><h2 id="exporting-a-multi-stage-event" tabindex="-1">Exporting a multi-stage event <a class="header-anchor" href="#exporting-a-multi-stage-event" aria-label="Permalink to &quot;Exporting a multi-stage event&quot;">​</a></h2><p>Both standings exports live on the <strong>Actions</strong> menu of the carnival&#39;s Standings tab, alongside Recompute.</p><p><strong>Overall standings as CSV</strong> — <strong>Export CSV</strong>. One row per competitor, one column per stage, plus the total: the shape a prize-giving spreadsheet wants. A stage that didn&#39;t count is bracketed rather than blanked, and a provisional total keeps its <code>*</code>, so the file says what the screen said. Export one class or all of them.</p><p><strong>Overall standings as PDF</strong> — <strong>Export PDF</strong>. The table laid out for printing or pinning up, matching whatever you have on screen: the class or combined view you have selected, and your Show and Times settings.</p><p><strong>IOF XML per stage</strong> — export a stage&#39;s results as IOF XML the usual way. Because the event is a stage, the file also carries the stage&#39;s <code>raceNumber</code> and each competitor&#39;s overall standing as an IOF <code>OverallResult</code>. That is the IOF standard&#39;s own answer to multi-stage results, so SplitsBrowser, Eventor and Livelox read it with no bespoke format. A standalone event&#39;s export is unchanged.</p><p>See <a href="./../event-setup/multi-stage-events#exporting-a-carnival">Multi-stage events</a>.</p><blockquote><p><strong>A knock-out competition&#39;s classification has no export yet</strong> — it is on screen only. Each round&#39;s own results export normally, as any event&#39;s do. See <a href="./../event-setup/knock-out-competitions">Knock-out competitions</a>.</p></blockquote><h2 id="exporting-as-orienteering-json" tabindex="-1">Exporting as Orienteering JSON <a class="header-anchor" href="#exporting-as-orienteering-json" aria-label="Permalink to &quot;Exporting as Orienteering JSON&quot;">​</a></h2><p>Everything Manager exports as IOF XML it also exports as <strong>Orienteering JSON</strong> — a published format with a JSON Schema, carrying the things the XML has no room for: split-time columns as data, a relay team&#39;s own result, whether a split came from a card or a radio, and millisecond precision. If you are writing something that reads a Manager event — a club results page, a spreadsheet pipeline, an app — that is the format to read.</p><p>See <a href="./../advanced/orienteering-json">Orienteering JSON (OJSON)</a> for the endpoints, the field reference and the schema.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../advanced/orienteering-json">Orienteering JSON (OJSON)</a> — the format behind every <strong>Export JSON</strong> menu</li><li><a href="./results">Results</a></li><li><a href="./../event-setup/competitors-clubs-teams#exporting-the-entry-list">Competitors and clubs</a> — exporting the entry list</li><li><a href="./../event-setup/multi-stage-events">Multi-stage events</a> — exporting overall standings</li><li><a href="./../event-setup/import-event-data">Importing event data</a></li></ul>',26)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
